import {configured,supabase,currentProfile,escapeHtml,money} from './supabase-client.js';
const modules=['ড্যাশবোর্ড','আয় ব্যবস্থাপনা','ব্যয় ব্যবস্থাপনা','দাতা ও অনুদান','ব্যাংক ও ক্যাশ','ট্রান্সফার','ক্যাশবুক ও লেজার','বকেয়া ও বিল','কর্মচারী ও বেতন','বাজেট ব্যবস্থাপনা','তহবিল ব্যবস্থাপনা','রসিদ ও ভাউচার','আর্থিক রিপোর্ট','PDF ও Excel','ট্রায়াল ব্যালান্স ও ব্যালান্স শিট','সার্চ','ব্যাংক রিকনসিলিয়েশন','অডিট ও যাচাই','অনুমোদন ব্যবস্থাপনা','অডিট ট্রেইল','ব্যবহারকারী ও অনুমতি','সেটিংস','বার্তা ও নোটিফিকেশন','মাসিক চাঁদা আদায়'];
let user,profile,members=[],dues=[],visibleModules=[],activeModule=0,chandaCanView=false,chandaCanWrite=false;
const moduleKeys=Object.fromEntries(modules.map((_,i)=>[i,'m'+String(62+i).padStart(2,'0')]));
const dhaka=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dhaka',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const today=dhaka;
const fmt=n=>new Intl.NumberFormat('bn-BD').format(n);
const el=id=>document.getElementById(id);
const currentInstitution=()=>el('adInstitution')?.value||(profile?.institution==='foundation'?'foundation':'mosque');
async function loadModuleVisibility(){
 const inst=currentInstitution(),keys=[...new Set(Object.values(moduleKeys))];
 const checks=await Promise.all(keys.map(async key=>{const {data,error}=await supabase.rpc('accounts_feature_access',{target_institution:inst,target_module:key,write_access:false});if(error)throw error;return [key,!!data]}));
 const allowed=new Set(checks.filter(x=>x[1]).map(x=>x[0]));
 chandaCanView=false;chandaCanWrite=false;
 if(inst==='mosque'){
  const [view,write]=await Promise.all([supabase.rpc('chanda_can_access',{write_access:false}),supabase.rpc('chanda_can_access',{write_access:true})]);
  if(view.error)throw view.error;if(write.error)throw write.error;
  chandaCanView=!!view.data;chandaCanWrite=!!write.data;
  if(chandaCanView)allowed.add(moduleKeys[23]);
 }
 const {data:messageAccess,error:messageError}=await supabase.rpc('accounts_message_access',{target_institution:inst,write_access:false});if(messageError)throw messageError;if(messageAccess)allowed.add(moduleKeys[22]);
 // Keep every visible item in the original 24-module order, independent of permission lookup order.
 visibleModules=Object.keys(moduleKeys).map(Number).filter(i=>allowed.has(moduleKeys[i]));
}
function refreshNav(){
 document.querySelectorAll('#adNav button').forEach(b=>{const i=Number(b.dataset.i);b.hidden=!visibleModules.includes(i);b.classList.toggle('active',i===activeModule)});
}
function resetAdPage(html=''){
 const page=el('adPage'),bin=el('adLegacyBin');
 [...page.children].forEach(node=>{if(node.classList.contains('ad-legacy-panel'))bin.appendChild(node);else node.remove()});
 if(html)page.innerHTML=html;
}
function movePanel(id){
 resetAdPage();
 const target=el(id);if(!target){el('adPage').innerHTML='<section class="module"><h2>'+escapeHtml(modules[activeModule])+'</h2><p>এই অংশের পুরোনো প্যানেল পাওয়া যায়নি।</p></section>';return}
 const panel=target.closest('.panel')||target;panel.hidden=false;panel.classList.add('ad-legacy-panel');el('adPage').appendChild(panel);
}
function mount(){
 if(el('accountsDashboard'))return;
 const root=document.createElement('section');root.id='accountsDashboard';
 root.innerHTML='<div class="layout"><aside class="side"><div class="brand"><b>SAKM-61</b><strong>Accounts Panel</strong><small>Transparency · Accountability · Trust</small></div><nav id="adNav"></nav><button class="action" id="adLogout" style="margin-top:16px;background:#b42c35">↪ লগআউট</button></aside><main class="main"><header class="top"><div class="top-brand"><img src="./assets/mosque-hero.webp" alt="শায়লা আকরাম কেন্দ্রীয় জামে মসজিদ"><div class="top-brand-copy"><b>SAKM-61 Accounts</b><span>শায়লা আকরাম কেন্দ্রীয় জামে মসজিদ</span><small>মসজিদ ও ফাউন্ডেশনের পৃথক হিসাব</small></div></div><div class="top-controls"><select id="adInstitution" aria-label="প্রতিষ্ঠান"></select><select id="adMonth" aria-label="মাস"></select><div id="adUser"></div></div></header><section class="hero"><div><h1 id="adTitle">ড্যাশবোর্ড</h1><p id="adSub">প্রতিষ্ঠানভিত্তিক আর্থিক সারসংক্ষেপ</p></div><div><button class="action green" id="adAdd" hidden>＋ নতুন চাঁদাদাতা</button> <button class="action" id="adReport" hidden>▥ রিপোর্ট</button></div></section><div id="adPage"></div><div id="adLegacyBin" hidden></div></main></div>';
 const app=el('app');app.prepend(root);[...app.children].filter(x=>x!==root).forEach(x=>{x.hidden=true});
 el('adNav').innerHTML=modules.map((m,i)=>'<button type="button" data-i="'+i+'"><span class="num">'+(i+1)+'</span>'+m+'</button>').join('');
 el('adNav').onclick=e=>{const b=e.target.closest('button[data-i]');if(b)openModule(+b.dataset.i)};
 const opts=profile?.institution==='both'?['mosque','foundation']:[profile?.institution==='foundation'?'foundation':'mosque'];
 el('adInstitution').innerHTML=opts.map(x=>'<option value="'+x+'">'+(x==='mosque'?'মসজিদ':'ফাউন্ডেশন')+'</option>').join('');
 el('adInstitution').value=opts[0];if(el('institution'))el('institution').value=opts[0];
 el('adInstitution').onchange=async()=>{if(el('institution')){el('institution').value=currentInstitution();el('institution').dispatchEvent(new Event('change',{bubbles:true}))}try{await loadModuleVisibility();refreshNav();const next=visibleModules.includes(activeModule)?activeModule:(visibleModules[0]??-1);if(next>=0)openModule(next);else el('adPage').innerHTML='<div class="panel empty">এই প্রতিষ্ঠানের কোনো Accounts মডিউলে আপনার অনুমতি নেই।</div>'}catch(e){showError(e)}};
 const now=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Dhaka'})),monthOptions=[];
 for(let i=-2;i<=3;i++){const d=new Date(now.getFullYear(),now.getMonth()+i,1);monthOptions.push('<option value="'+d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'">'+new Intl.DateTimeFormat('bn-BD',{month:'long',year:'numeric'}).format(d)+'</option>')}
 el('adMonth').innerHTML=monthOptions.join('');
 const target=new Date(now.getFullYear(),now.getMonth()+(now.getDate()>=20?1:0),1);el('adMonth').value=target.getFullYear()+'-'+String(target.getMonth()+1).padStart(2,'0');
 el('adMonth').onchange=()=>{if(activeModule===23)loadChanda().catch(showError)};
 el('adAdd').onclick=memberForm;el('adReport').onclick=exportExcel;el('adLogout').onclick=()=>el('logout')?.click();
 refreshNav();
}
function openModule(i){
 if(!visibleModules.includes(i))return;
 activeModule=i;refreshNav();el('adTitle').textContent=modules[i];el('adSub').textContent='হিসাব বিভাগের '+modules[i]+' · '+(currentInstitution()==='mosque'?'মসজিদ':'ফাউন্ডেশন');
 el('adAdd').hidden=!(i===23&&currentInstitution()==='mosque'&&chandaCanWrite);el('adReport').hidden=!(i===23&&currentInstitution()==='mosque'&&chandaCanView);el('adMonth').hidden=i!==23||currentInstitution()!=='mosque';
 if(i===0){renderDashboard().catch(showError);return}
 if(i===3){renderDonations().catch(showError);return}
 if(i===4){renderBankAccounts().catch(showError);return}
 if(i===5){renderTransfers().catch(showError);return}
 if(i===6){renderCashbookJournal().catch(showError);return}
 if(i===12){renderReports().catch(showError);return}
 if(i===13){renderReports(true).catch(showError);return}
 if(i===14){renderTrialBalance().catch(showError);return}
 if(i===15){renderAdvancedSearch().catch(showError);return}
 if(i===16){renderReconciliation().catch(showError);return}
 if(i===17){renderAuditReview().catch(showError);return}
 if(i===18){renderApprovals().catch(showError);return}
 if(i===19){renderAuditTrail().catch(showError);return}
 if(i===20){renderUserPermissions().catch(showError);return}
 if(i===21){renderSettings().catch(showError);return}
 if(i===22){renderMessageCenter().catch(showError);return}
 if(i===23){renderMonthlyChanda().catch(showError);return}
 const map={1:'entryForm',2:'entryForm',7:'obligationsPanel',8:'payrollPanel',9:'budgetForm',10:'fundRows',11:'entries'};
 const id=map[i];if(id){movePanel(id);if((i===1||i===2)&&el('type'))el('type').value=i===1?'income':'expense';return}
 el('adPage').innerHTML='<section class="module"><h2>'+escapeHtml(modules[i])+'</h2><p>এই মডিউলটি এই প্রতিষ্ঠানের জন্য এখনো সংযুক্ত নয়।</p></section>';
}
function showError(e){const p=el('adPage');if(p)p.insertAdjacentHTML('afterbegin','<div class="note" style="color:#a11">'+escapeHtml(e?.message||String(e))+'</div>');else console.error(e)}
async function renderDashboard(){
 const p=el('adPage'),inst=currentInstitution();resetAdPage('<div class="panel"><div class="empty">লাইভ হিসাব লোড হচ্ছে…</div></div>');
 const rows=[];let offset=0;
 while(true){
  const {data,error}=await supabase.from('ledger_entries').select('entry_type,amount,status,entry_date').eq('institution',inst).order('entry_date',{ascending:false}).order('id',{ascending:true}).range(offset,offset+999);
  if(error)throw error;
  const batch=data||[];rows.push(...batch);
  if(batch.length<1000)break;
  offset+=1000;
 }
 const approved=rows.filter(x=>x.status==='approved'),pending=rows.filter(x=>x.status==='pending');
 const income=approved.filter(x=>x.entry_type==='income').reduce((n,x)=>n+Number(x.amount||0),0),expense=approved.filter(x=>x.entry_type==='expense').reduce((n,x)=>n+Number(x.amount||0),0);
 p.innerHTML='<div class="stats"><div class="stat greenstat"><div><small>অনুমোদিত মোট আয়</small><strong>'+money(income)+'</strong></div></div><div class="stat redstat"><div><small>অনুমোদিত মোট ব্যয়</small><strong>'+money(expense)+'</strong></div></div><div class="stat bluestat"><div><small>বর্তমান স্থিতি</small><strong>'+money(income-expense)+'</strong></div></div><div class="stat yellowstat"><div><small>অনুমোদনের অপেক্ষায়</small><strong>'+fmt(pending.length)+'টি</strong></div></div></div><section class="panel"><div class="head"><h2>'+(inst==='mosque'?'মসজিদ':'ফাউন্ডেশন')+' — সাম্প্রতিক হিসাব</h2></div><div class="body tablewrap"><table><thead><tr><th>তারিখ</th><th>ধরন</th><th>খাত</th><th>পরিমাণ</th><th>অবস্থা</th></tr></thead><tbody>'+rows.slice(0,20).map(x=>'<tr><td>'+escapeHtml(x.entry_date)+'</td><td>'+escapeHtml(x.entry_type)+'</td><td>—</td><td>'+money(x.amount)+'</td><td>'+escapeHtml(x.status)+'</td></tr>').join('')+'</tbody></table></div></section>';
}
async function renderDonations(){
 const p=el('adPage'),inst=currentInstitution();
 resetAdPage('<section class="panel"><div class="head"><h2>দাতা, অনুদান ও মাসিক চাঁদা</h2></div><div class="body"><div id="adDonorArea"><div class="empty">দাতার তথ্য লোড হচ্ছে…</div></div></div></section>');
 const [view,perm]=await Promise.all([
  supabase.rpc('accounts_feature_access',{target_institution:inst,target_module:'m65',write_access:false}),
  supabase.rpc('accounts_feature_access',{target_institution:inst,target_module:'m65',write_access:true})
 ]);
 if(view.error)throw view.error;if(perm.error)throw perm.error;
 const result=view.data?await supabase.from('account_donors').select('id,donor_name,mobile,address,donor_type,notes,is_active,created_at').eq('institution',inst).order('created_at',{ascending:false}).limit(500):{data:[],error:null};
 if(result.error)throw result.error;const donors=result.data||[],host=el('adDonorArea');
 if(view.data){
  host.innerHTML=(perm.data?'<form class="form" id="adDonorForm"><label>দাতার নাম<input name="name" required maxlength="160"></label><label>মোবাইল<input name="mobile" maxlength="30"></label><label>ঠিকানা<input name="address" maxlength="300"></label><label>দাতার ধরন<select name="kind"><option value="individual">ব্যক্তি</option><option value="organization">প্রতিষ্ঠান</option><option value="anonymous">নাম প্রকাশে অনিচ্ছুক</option></select></label><label class="wide">নোট<input name="notes" maxlength="500"></label><div class="wide"><button class="action green">দাতা সংরক্ষণ</button></div></form>':'')+'<div class="toolbar"><input id="adDonorSearch" placeholder="নাম, মোবাইল বা ঠিকানা দিয়ে খুঁজুন"><button class="action light" id="adDonorCsv">CSV এক্সপোর্ট</button></div><div class="tablewrap"><table><thead><tr><th>#</th><th>দাতার নাম</th><th>মোবাইল</th><th>ঠিকানা</th><th>ধরন</th><th>অবস্থা</th></tr></thead><tbody id="adDonorRows"></tbody></table></div><div class="note">দাতা নিবন্ধন, অনুদান ও মাসিক চাঁদা একই Donations মডিউলে রাখা হয়েছে।</div>';
  const draw=()=>{const q=el('adDonorSearch').value.trim().toLowerCase(),filtered=donors.filter(x=>[x.donor_name,x.mobile,x.address].join(' ').toLowerCase().includes(q));el('adDonorRows').innerHTML=filtered.map((x,i)=>'<tr><td>'+fmt(i+1)+'</td><td>'+escapeHtml(x.donor_name)+'</td><td>'+escapeHtml(x.mobile||'—')+'</td><td>'+escapeHtml(x.address||'—')+'</td><td>'+escapeHtml(x.donor_type)+'</td><td>'+(x.is_active?'সক্রিয়':'নিষ্ক্রিয়')+'</td></tr>').join('')||'<tr><td colspan="6" class="empty">কোনো দাতা পাওয়া যায়নি।</td></tr>'};
  draw();el('adDonorSearch').oninput=draw;
  el('adDonorCsv').onclick=()=>{const csv=['নাম,মোবাইল,ঠিকানা,ধরন,নোট',...donors.map(x=>[x.donor_name,x.mobile,x.address,x.donor_type,x.notes].map(v=>'"'+String(v||'').replace(/"/g,'""')+'"').join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download='SAKM-61-donors-'+inst+'.csv';a.click();URL.revokeObjectURL(a.href)};
  if(perm.data)el('adDonorForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const {error}=await supabase.from('account_donors').insert({institution:inst,donor_name:String(f.get('name')).trim(),mobile:String(f.get('mobile')||'').trim(),address:String(f.get('address')||'').trim(),donor_type:String(f.get('kind')),notes:String(f.get('notes')||''),created_by:user.id});if(error)throw error;alert('দাতা সংরক্ষণ হয়েছে।');await renderDonations()}catch(err){alert(err.message||String(err))}};
  const fund=el('fundRows');if(fund){const {data:fundAccess,error}=await supabase.rpc('accounts_feature_access',{target_institution:inst,target_module:'m72',write_access:false});if(error)throw error;if(fundAccess){const panel=fund.closest('.panel');panel.classList.add('ad-legacy-panel');p.appendChild(panel)}}
 }else host.innerHTML='<div class="note">দাতা ও অনুদান তালিকার অনুমতি নেই। মাসিক চাঁদা ব্যবস্থাপনা থাকলে নিচের অংশে ব্যবহার করুন।</div>';
 if(inst==='mosque'&&chandaCanView){p.insertAdjacentHTML('beforeend','<section class="panel"><div class="head"><h2>মাসিক চাঁদা আদায়</h2></div><div class="body" id="adChandaContent"><div class="empty">চাঁদার তথ্য লোড হচ্ছে…</div></div></section>');await loadChanda()}
}
