 host.innerHTML=(canWrite?'<form class="form" id="adBankForm"><label>হিসাবের নাম<input name="name" required maxlength="140"></label><label>ব্যাংক / সেবা প্রতিষ্ঠানের নাম<input name="bank" maxlength="140"></label><label>অ্যাকাউন্ট নম্বর (শুধু শেষ ৪ সংখ্যা সংরক্ষিত হবে)<input name="number" maxlength="40"></label><label>ধরন<select name="kind"><option value="cash">নগদ</option><option value="bank">ব্যাংক</option><option value="mobile_banking">মোবাইল ব্যাংকিং</option></select></label><label>প্রারম্ভিক স্থিতি<input name="opening" type="number" min="0" step=".01" value="0" required></label><div class="wide"><button class="action green">হিসাব যোগ করুন</button></div></form>':'')+'<div class="tablewrap"><table><thead><tr><th>হিসাব</th><th>ব্যাংক/সেবা</th><th>মাস্কড নম্বর</th><th>ধরন</th><th>কোড</th><th>প্রারম্ভিক স্থিতি</th><th>বর্তমান স্থিতি</th><th>অবস্থা</th></tr></thead><tbody>'+accounts.map(a=>'<tr><td>'+escapeHtml(a.account_name)+'</td><td>'+escapeHtml(a.institution_name||'—')+'</td><td>'+escapeHtml(a.account_number_masked||'—')+'</td><td>'+escapeHtml(a.account_kind)+'</td><td>'+escapeHtml(a.account_code)+'</td><td>'+money(a.opening_balance)+'</td><td><b>'+money(a.book_balance)+'</b></td><td>'+(a.is_active?'সক্রিয়':'নিষ্ক্রিয়')+'</td></tr>').join('')+'</tbody></table></div>';
