 const opts=(chart.data||[]).map(a=>'<option value="'+escapeHtml(a.account_code)+'">'+escapeHtml(a.account_code)+' · '+escapeHtml(a.account_name)+' ('+escapeHtml(a.account_type)+')</option>').join('');
