 const journalRows=host.querySelector('#adJournalRows');if(journalRows)journalRows.onclick=async e=>{const b=e.target.closest('[data-reverse-journal]');if(!b)return;const reason=prompt('রিভার্স/সংশোধনের কারণ লিখুন (আবশ্যক)','');if(reason===null)return;if(!reason.trim()){alert('কারণ লিখতে হবে।');return}if(!confirm('মূল জার্নাল মুছে ফেলা হবে না; বিপরীত ডেবিট-ক্রেডিট দিয়ে নতুন সংশোধনী জার্নাল তৈরি হবে। চালিয়ে যাবেন?'))return;try{const {data,error}=await supabase.rpc('account_reverse_journal',{p_journal:b.dataset.reverseJournal,p_reason:reason.trim()});if(error)throw error;alert('সংশোধনী জার্নাল তৈরি হয়েছে: '+data);await renderCashbookJournal()}catch(err){alert(err.message||String(err))}};
