function stateOf(m,d,day,upcoming,today){if(d&&Number(d.paid_amount)>=Number(d.amount))return ['paid','✓','আদায় সম্পন্ন'];if(d&&Number(d.paid_amount)>0)return ['partial','◒','আংশিক আদায়'];if(upcoming&&day>=20&&day<=24)return ['warning','◷','সময় ঘনিয়ে এসেছে'];if(upcoming&&day>=25)return ['collect','!','নতুন মাসের চাঁদা সংগ্রহ'];if(d&&today>=d.due_date)return ['overdue','!','বকেয়া'];return ['neutral','·','অপেক্ষমাণ']}
async function loadChanda(){
 const p=el('adChandaContent')||el('adPage');if(currentInstitution()!=='mosque')return;p.innerHTML='<div class="panel"><div class="empty">লাইভ ডেটা লোড হচ্ছে…</div></div>';
 const month=el('adMonth').value+'-01',today=dhaka(),day=+today.slice(8,10),upcoming=month.slice(0,7)>today.slice(0,7);
 const {data:canWrite,error:writeErr}=await supabase.rpc('chanda_can_access',{write_access:true});if(writeErr)throw writeErr;if(canWrite){const {error:dueErr}=await supabase.rpc('ensure_chanda_dues_for_month',{target_month:month});if(dueErr)throw dueErr}
 const [mr,dr]=await Promise.all([supabase.from('chanda_members').select('id,member_name,father_name,address,phone,monthly_amount,due_day,status').eq('status','active').order('member_name'),supabase.from('chanda_dues').select('id,member_id,due_month,due_date,amount,paid_amount,status,paid_at').eq('due_month',month)]);
 if(mr.error)throw mr.error;if(dr.error)throw dr.error;members=mr.data||[];dues=dr.data||[];chandaCanWrite=!!canWrite;el('adAdd').hidden=!chandaCanWrite;el('adReport').hidden=!chandaCanWrite;
 const byId=new Map(dues.map(d=>[d.member_id,d])),rows=members.map(m=>({m,d:byId.get(m.id)||null}));
 const counts={paid:0,partial:0,warning:0,collect:0,overdue:0,neutral:0};rows.forEach(x=>counts[stateOf(x.m,x.d,day,upcoming,today)[0]]++);
 const total=rows.length,paidAmount=rows.reduce((s,x)=>s+Number(x.d?.paid_amount||0),0),dueAmount=rows.reduce((s,x)=>s+Number(x.d?.amount||x.m.monthly_amount),0),remaining=Math.max(0,dueAmount-paidAmount),pct=total?Math.round(counts.paid/total*100):0;
 p.innerHTML='<div class="stats"><div class="stat greenstat"><span class="ico">☑</span><div><small>মোট আদায় সম্পন্ন</small><strong>'+fmt(counts.paid)+' জন</strong><em>'+money(paidAmount)+'</em></div></div><div class="stat yellowstat"><span class="ico">◷</span><div><small>সময় ঘনিয়ে এসেছে</small><strong>'+fmt(counts.warning)+' জন</strong><em>২০–২৪ তারিখ সতর্কতা</em></div></div><div class="stat redstat"><span class="ico">⚠</span><div><small>বকেয়া / নতুন মাসের সংগ্রহ</small><strong>'+fmt(counts.overdue+counts.collect)+' জন</strong><em>অবশিষ্ট '+money(remaining)+'</em></div></div><div class="stat bluestat"><span class="ico">♟</span><div><small>মোট সদস্য</small><strong>'+fmt(total)+' জন</strong><em>নির্ধারিত '+money(dueAmount)+'</em></div></div></div><div class="columns"><section class="panel"><div class="head"><h2>♟ চাঁদাদাতাদের তালিকা</h2><span>'+new Intl.DateTimeFormat('bn-BD',{month:'long',year:'numeric'}).format(new Date(month))+'</span></div><div class="body"><div class="toolbar"><input id="adSearch" placeholder="নাম, ঠিকানা বা মোবাইল দিয়ে খুঁজুন"><select id="adFilter"><option value="all">সব অবস্থা</option><option value="paid">আদায় সম্পন্ন</option><option value="warning">সময় ঘনিয়ে এসেছে</option><option value="collect">নতুন মাসের সংগ্রহ</option><option value="overdue">প্রকৃত বকেয়া</option><option value="partial">আংশিক আদায়</option></select><button class="action light" id="adRefresh">রিফ্রেশ</button></div><div class="tablewrap"><table><thead><tr><th>#</th><th>চাঁদাদাতার নাম</th><th>ঠিকানা</th><th>মোবাইল নম্বর</th><th>মাসিক চাঁদা</th><th>অবস্থা</th><th>শেষ জমার তারিখ</th><th>অ্যাকশন</th></tr></thead><tbody id="adRows"></tbody></table></div><div class="note">২০–২৪ তারিখ হলুদ সতর্কতা; ২৫ তারিখ থেকে নতুন মাসের সংগ্রহ লাল দেখাবে। পরবর্তী মাসের ১ তারিখ পার হলে অনাদায়ী পাওনা প্রকৃত বকেয়া হবে। সম্পূর্ণ টাকা জমা হলেই সবুজ হবে; আংশিক জমা নীল থাকবে।</div></div></section><aside><section class="panel"><div class="head"><h2>▥ মাসিক অগ্রগতি</h2></div><div class="body"><div class="ring" style="--pct:'+pct+'%"><div><strong>'+fmt(pct)+'%</strong><span>আদায় সম্পন্ন</span></div></div><div class="legend"><div><i class="dot" style="background:#12b96a"></i>আদায় হয়েছে　'+fmt(counts.paid)+' জন</div><div><i class="dot" style="background:#f3c21b"></i>সময় ঘনিয়ে এসেছে　'+fmt(counts.warning)+' জন</div><div><i class="dot" style="background:#ed4c4c"></i>নতুন মাসের সংগ্রহ / বকেয়া　'+fmt(counts.collect+counts.overdue)+' জন</div><div><i class="dot" style="background:#6ca8e8"></i>আংশিক　'+fmt(counts.partial)+' জন</div></div><div class="mini">মোট নির্ধারিত<b>'+money(dueAmount)+'</b></div><div class="mini">এ মাসে আদায়<b>'+money(paidAmount)+'</b></div><div class="mini">অবশিষ্ট<b>'+money(remaining)+'</b></div></div></section><section class="panel"><div class="head"><h2>⇩ কুইক লিংক</h2></div><div class="body"><button class="action green" id="adExcel">Excel ডাউনলোড</button> <button class="action" id="adPrint">প্রিন্ট / PDF</button> <button class="action purple" id="adHistory">আদায়ের ইতিহাস</button></div></section></aside></div>';
 function draw(){const q=el('adSearch').value.trim().toLowerCase(),f=el('adFilter').value;const filtered=rows.filter(x=>{const s=stateOf(x.m,x.d,day,upcoming,today)[0];return(!q||[x.m.member_name,x.m.address,x.m.phone].join(' ').toLowerCase().includes(q))&&(f==='all'||f===s)});el('adRows').innerHTML=filtered.map((x,i)=>{const s=stateOf(x.m,x.d,day,upcoming,today),d=x.d;return '<tr><td>'+fmt(i+1)+'</td><td><b>'+escapeHtml(x.m.member_name)+'</b></td><td>'+escapeHtml(x.m.address||'—')+'</td><td>'+escapeHtml(x.m.phone||'—')+'</td><td>'+money(x.m.monthly_amount)+'</td><td><span class="status '+s[0]+'">'+s[1]+' '+s[2]+'</span>'+(d&&Number(d.paid_amount)>0&&d.status!=='paid'?'<div style="font-size:11px">জমা '+money(d.paid_amount)+' / '+money(d.amount)+'</div>':'')+'</td><td>'+(d?.paid_at?new Date(d.paid_at).toLocaleDateString('bn-BD',{timeZone:'Asia/Dhaka'}):'—')+'</td><td>'+(d&&d.status!=='paid'&&chandaCanWrite?'<button class="action" data-pay="'+x.m.id+'" data-due="'+d.id+'">চাঁদা গ্রহণ</button>':d?'সম্পন্ন':'পাওনার রেকর্ড নেই')+'</td></tr>'}).join('')||'<tr><td colspan="8" class="empty">কোনো সদস্য বা রেকর্ড নেই।</td></tr>'}
 draw();el('adSearch').oninput=draw;el('adFilter').onchange=draw;el('adRefresh').onclick=()=>loadChanda().catch(showError);
 el('adRows').onclick=async e=>{const b=e.target.closest('[data-pay]');if(!b)return;const d=dues.find(x=>x.id===b.dataset.due),m=members.find(x=>x.id===b.dataset.pay);if(!d)return;const left=Number(d.amount)-Number(d.paid_amount),a=prompt('কত টাকা গ্রহণ করা হয়েছে? বাকি '+money(left),String(left));if(a===null)return;const amount=Number(a);if(!Number.isFinite(amount)||amount<=0||amount>left){alert('সঠিক পরিমাণ লিখুন।');return}const method=prompt('মাধ্যম: cash / bank / bkash / nagad / other','cash');if(method===null)return;const receiptWindow=window.open('','_blank');try{const {data:id,error}=await supabase.rpc('record_chanda_payment',{target_due:d.id,paid_amount:amount,paid_on:today(),method:method.trim(),reference:'',memo:''});if(error)throw error;const w=receiptWindow;if(w){w.document.write('<html lang="bn"><meta charset="utf-8"><title>চাঁদার রসিদ</title><h2 style="text-align:center">শায়লা আকরাম কেন্দ্রীয় জামে মসজিদ</h2><h3 style="text-align:center">মাসিক চাঁদা আদায়ের রসিদ</h3><p>রসিদ আইডি: '+escapeHtml(id)+'</p><p>নাম: '+escapeHtml(m.member_name)+'</p><p>মাস: '+escapeHtml(d.due_month)+'</p><p>জমা: '+money(amount)+'</p><p>মাধ্যম: '+escapeHtml(method)+'</p><p>তারিখ: '+today()+'</p><p>অবশিষ্ট: '+money(left-amount)+'</p><script>window.onload=()=>window.print()<\/script></html>');w.document.close()}else alert('পেমেন্ট সংরক্ষিত হয়েছে; রসিদ দেখতে পপ-আপ অনুমতি দিন।');await loadChanda()}catch(err){if(receiptWindow&&!receiptWindow.closed)receiptWindow.close();alert(err.message||String(err))}};
 el('adExcel').onclick=exportExcel;el('adPrint').onclick=()=>window.print();el('adHistory').onclick=paymentHistory;
}
function memberForm(){(el('adChandaContent')||el('adPage')).insertAdjacentHTML('afterbegin','<section class="panel"><div class="head"><h2>নতুন চাঁদাদাতা যোগ করুন</h2></div><div class="body"><form class="form" id="adMemberForm"><label>চাঁদাদাতার নাম<input name="name" required maxlength="140"></label><label>পিতার নাম<input name="father" maxlength="140"></label><label>ঠিকানা<input name="address" maxlength="300"></label><label>মোবাইল নম্বর<input name="phone" maxlength="20"></label><label>মাসিক চাঁদা (টাকা)<input name="amount" type="number" min="1" step=".01" required></label><label>চাঁদা পরিশোধের নির্ধারিত সময়<input value="প্রতি মাসের ১ তারিখের মধ্যে" disabled></label><label class="wide">নোট<textarea name="notes"></textarea></label><div class="wide"><button class="action green">সদস্য সংরক্ষণ</button></div></form></div></section>');el('adMemberForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const phone=String(f.get('phone')||'').trim();if(phone){const {data:duplicates,error:duplicateError}=await supabase.from('chanda_members').select('member_name').eq('phone',phone).eq('status','active').limit(10);if(duplicateError)throw duplicateError;if((duplicates||[]).length&&!confirm('এই মোবাইল নম্বরটি আগে '+duplicates.map(x=>x.member_name).join(', ')+' নামের সদস্যের জন্য আছে। একই নম্বর ব্যবহার করতে নিশ্চিত?'))return}const {error}=await supabase.from('chanda_members').insert({institution:'mosque',member_name:String(f.get('name')).trim(),father_name:String(f.get('father')||'').trim(),address:String(f.get('address')||'').trim(),phone,monthly_amount:Number(f.get('amount')),due_day:1,created_by:user.id,status:'active',contact_consent:false,reminder_channel:'in_app',notes:String(f.get('notes')||'')});if(error)throw error;alert('চাঁদাদাতা সংরক্ষিত হয়েছে।');await loadChanda()}catch(err){alert(err.message||String(err))}}}
async function paymentHistory(){const {data,error}=await supabase.from('chanda_payments').select('id,member_id,due_id,amount,payment_date,payment_method,reference_no').order('created_at',{ascending:false}).limit(300);if(error){showError(error);return}const ids=[...new Set(data.map(x=>x.member_id))];let names={};if(ids.length){const r=await supabase.from('chanda_members').select('id,member_name').in('id',ids);if(r.error)throw r.error;(r.data||[]).forEach(x=>names[x.id]=x.member_name)}(el('adChandaContent')||el('adPage')).insertAdjacentHTML('afterbegin','<section class="panel"><div class="head"><h2>চাঁদা আদায়ের ইতিহাস</h2></div><div class="body tablewrap"><table><thead><tr><th>তারিখ</th><th>নাম</th><th>পাওনা আইডি</th><th>পরিমাণ</th><th>মাধ্যম</th><th>রসিদ আইডি</th></tr></thead><tbody>'+data.map(x=>'<tr><td>'+x.payment_date+'</td><td>'+escapeHtml(names[x.member_id]||'—')+'</td><td>'+x.due_id+'</td><td>'+money(x.amount)+'</td><td>'+escapeHtml(x.payment_method)+'</td><td>'+x.id+'</td></tr>').join('')+'</tbody></table></div></section>')}
function exportExcel(){const rows=members.map(m=>{const d=dues.find(x=>x.member_id===m.id);return{নাম:m.member_name,ঠিকানা:m.address,মোবাইল:m.phone,মাসিক_চাঁদা:+m.monthly_amount,জমা:+(d?.paid_amount||0),বাকি:Math.max(0,+(d?.amount||m.monthly_amount)-+(d?.paid_amount||0)),অবস্থা:d?.status||'পাওনা তৈরি হয়নি'}});import('https://esm.sh/xlsx@0.18.5').then(X=>{const ws=X.utils.json_to_sheet(rows),wb=X.utils.book_new();X.utils.book_append_sheet(wb,ws,'মাসিক চাঁদা');X.writeFile(wb,'SAKM-61-monthly-chanda.xlsx')}).catch(e=>alert(e.message))}
async function start(){if(!configured||!el('app')||el('app').hidden||el('accountsDashboard'))return;try{const x=await currentProfile();user=x.user;profile=x.profile;if(!user||!profile)return;mount();el('adUser').textContent=(profile.full_name||'Accounts User')+' · '+profile.role;if(el('institution')&&profile.institution!=='both')el('institution').value=profile.institution;await loadModuleVisibility();refreshNav();if(!visibleModules.length){el('adPage').innerHTML='<div class="panel empty">এই প্রতিষ্ঠানের Accounts মডিউলে আপনার অনুমতি নেই।</div>';return}const first=visibleModules.includes(0)?0:visibleModules[0];openModule(first)}catch(e){showError(e)}}
const app=el('app');if(app){new MutationObserver(()=>{if(!app.hidden&&!el('accountsDashboard'))start()}).observe(app,{attributes:true,attributeFilter:['hidden']});if(!app.hidden)start()}
